// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {PackedUserOperation} from "./interfaces/PackedUserOperation.sol";

/// @title AgentPaymaster
/// @notice ERC-4337 v0.7 paymaster with a per-agent rolling gas sponsorship budget.
/// @dev `paymasterAndData` is encoded as `(address agent,uint48 validUntil,uint48 validAfter,uint256 declaredGas)`.
contract AgentPaymaster {
    enum PostOpMode {
        opSucceeded,
        opReverted,
        postOpReverted
    }

    error UnauthorizedEntryPoint(address caller);
    error UnauthorizedOwner(address caller);
    error InvalidAddress();
    error InvalidPaymasterData();
    error AgentNotRegistered(address account, address agent);
    error PaymasterDailyGasLimitExceeded(address agent, uint256 projected, uint256 limit);
    error InvalidGasDeclaration();
    error InvalidValidityWindow(uint48 validUntil, uint48 validAfter);
    error InvalidContext();
    error InsufficientReservedGas(address agent, uint256 requested, uint256 reserved);
    error WithdrawFailed();

    address public immutable entryPoint;
    address public owner;
    uint256 public immutable defaultDailyGasLimit;

    mapping(address account => address agent) public accountAgent;
    mapping(address agent => uint256 limit) public agentDailyGasLimit;
    mapping(address agent => uint256 spent) public agentSpentGas;
    mapping(address agent => uint256 reserved) public agentReservedGas;
    mapping(address agent => uint256 windowStart) public agentWindowStart;

    event OwnerUpdated(address indexed previousOwner, address indexed newOwner);
    event AgentRegistered(address indexed account, address indexed agent, uint256 dailyGasLimit);
    event AgentUnregistered(address indexed account, address indexed agent);
    event SponsorshipReserved(bytes32 indexed userOpHash, address indexed agent, uint256 declaredGas);
    event SponsorshipSettled(bytes32 indexed userOpHash, address indexed agent, uint256 actualGas, uint256 declaredGas);
    event DailyGasLimitUpdated(address indexed agent, uint256 dailyGasLimit);

    modifier onlyOwner() {
        if (msg.sender != owner) revert UnauthorizedOwner(msg.sender);
        _;
    }

    modifier onlyEntryPoint() {
        if (msg.sender != entryPoint) revert UnauthorizedEntryPoint(msg.sender);
        _;
    }

    constructor(address entryPoint_, address owner_, uint256 defaultDailyGasLimit_) payable {
        if (entryPoint_ == address(0) || owner_ == address(0)) revert InvalidAddress();
        if (defaultDailyGasLimit_ == 0) revert InvalidGasDeclaration();
        entryPoint = entryPoint_;
        owner = owner_;
        defaultDailyGasLimit = defaultDailyGasLimit_;
    }

    /// @notice Changes the paymaster administrator.
    function setOwner(address newOwner) external onlyOwner {
        if (newOwner == address(0)) revert InvalidAddress();
        emit OwnerUpdated(owner, newOwner);
        owner = newOwner;
    }

    /// @notice Registers the agent permitted to sponsor operations from an account.
    function registerAgent(address account, address agent, uint256 dailyGasLimit) external onlyOwner {
        if (account == address(0) || agent == address(0)) revert InvalidAddress();
        if (dailyGasLimit == 0) revert InvalidGasDeclaration();
        accountAgent[account] = agent;
        agentDailyGasLimit[agent] = dailyGasLimit;
        if (agentWindowStart[agent] == 0) agentWindowStart[agent] = block.timestamp;
        emit AgentRegistered(account, agent, dailyGasLimit);
    }

    /// @notice Removes an account-to-agent sponsorship binding.
    function unregisterAgent(address account) external onlyOwner {
        address agent = accountAgent[account];
        delete accountAgent[account];
        emit AgentUnregistered(account, agent);
    }

    /// @notice Updates the rolling gas budget for an already registered agent.
    function setAgentDailyGasLimit(address agent, uint256 dailyGasLimit) external onlyOwner {
        if (agent == address(0) || dailyGasLimit == 0) revert InvalidGasDeclaration();
        agentDailyGasLimit[agent] = dailyGasLimit;
        emit DailyGasLimitUpdated(agent, dailyGasLimit);
    }

    /// @notice Reserves the declared gas budget before EntryPoint execution.
    function validatePaymasterUserOp(
        PackedUserOperation calldata userOp,
        bytes32 userOpHash,
        uint256 maxCost
    ) external onlyEntryPoint returns (bytes memory context, uint256 validationData) {
        maxCost;
        (address agent, uint48 validUntil, uint48 validAfter, uint256 declaredGas) = _decodePaymasterData(userOp.paymasterAndData);
        if (accountAgent[userOp.sender] != agent || agentDailyGasLimit[agent] == 0) {
            revert AgentNotRegistered(userOp.sender, agent);
        }
        if (declaredGas == 0) revert InvalidGasDeclaration();
        if (validUntil != 0 && validUntil <= validAfter) revert InvalidValidityWindow(validUntil, validAfter);
        _refresh(agent);
        uint256 limit = agentDailyGasLimit[agent];
        uint256 projected = agentSpentGas[agent] + agentReservedGas[agent] + declaredGas;
        if (projected > limit) revert PaymasterDailyGasLimitExceeded(agent, projected, limit);
        agentReservedGas[agent] += declaredGas;
        context = abi.encode(agent, declaredGas, userOpHash);
        validationData = _packValidationData(validUntil, validAfter);
        emit SponsorshipReserved(userOpHash, agent, declaredGas);
    }

    /// @notice Settles reserved gas and keeps the actual billed gas inside the budget.
    function postOp(
        PostOpMode,
        bytes calldata context,
        uint256 actualGasCost,
        uint256 actualUserOpFeePerGas
    ) external onlyEntryPoint {
        (address agent, uint256 declaredGas, bytes32 userOpHash) = abi.decode(context, (address, uint256, bytes32));
        _refresh(agent);
        if (agentReservedGas[agent] < declaredGas) revert InsufficientReservedGas(agent, declaredGas, agentReservedGas[agent]);
        uint256 actualGas = declaredGas;
        if (actualUserOpFeePerGas != 0) {
            uint256 measuredGas = actualGasCost / actualUserOpFeePerGas;
            if (measuredGas < actualGas) actualGas = measuredGas;
        }
        agentReservedGas[agent] -= declaredGas;
        agentSpentGas[agent] += actualGas;
        emit SponsorshipSettled(userOpHash, agent, actualGas, declaredGas);
    }

    /// @notice Deposits native currency into the canonical EntryPoint.
    function deposit() external payable onlyOwner {
        IEntryPointDeposit(entryPoint).depositTo{value: msg.value}(address(this));
    }

    /// @notice Withdraws native currency from the canonical EntryPoint.
    function withdrawTo(address payable recipient, uint256 amount) external onlyOwner {
        if (recipient == address(0)) revert InvalidAddress();
        IEntryPointDeposit(entryPoint).withdrawTo(recipient, amount);
    }

    receive() external payable {}

    function _decodePaymasterData(bytes calldata data)
        internal
        pure
        returns (address agent, uint48 validUntil, uint48 validAfter, uint256 declaredGas)
    {
        if (data.length != 128) revert InvalidPaymasterData();
        (agent, validUntil, validAfter, declaredGas) = abi.decode(data, (address, uint48, uint48, uint256));
    }

    /// @notice Decodes the paymaster-specific payload format.
    function decodePaymasterData(bytes calldata data)
        external
        pure
        returns (address agent, uint48 validUntil, uint48 validAfter, uint256 declaredGas)
    {
        (agent, validUntil, validAfter, declaredGas) = abi.decode(data, (address, uint48, uint48, uint256));
    }

    function _refresh(address agent) internal {
        uint256 start = agentWindowStart[agent];
        if (start == 0 || block.timestamp >= start + 24 hours) {
            agentWindowStart[agent] = block.timestamp;
            agentSpentGas[agent] = 0;
            agentReservedGas[agent] = 0;
        }
    }

    function _packValidationData(uint48 validUntil, uint48 validAfter) internal pure returns (uint256) {
        return (uint256(validUntil) << 160) | (uint256(validAfter) << 208);
    }
}

interface IEntryPointDeposit {
    function depositTo(address account) external payable;
    function withdrawTo(address payable withdrawAddress, uint256 withdrawAmount) external;
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IAccount} from "./interfaces/IAccount.sol";
import {UserOperation} from "./interfaces/UserOperation.sol";
import {PackedUserOperation} from "./interfaces/PackedUserOperation.sol";
import {PolicyEngine} from "./PolicyEngine.sol";
import {SignatureLib} from "./libraries/SignatureLib.sol";
import {AnomalyGuard} from "./AnomalyGuard.sol";
import {GuardianRecoveryModule} from "./GuardianRecoveryModule.sol";

/// @title AgentSmartAccount
/// @notice ERC-4337 smart account with a root owner and a constrained session key.
/// @dev The account accepts both ERC-4337 v0.6 and v0.7 validation structs. Agent
///      execution is limited to the exact `execute` payload validated by PolicyEngine.
contract AgentSmartAccount is IAccount {
    using SignatureLib for bytes32;

    error UnauthorizedEntryPoint(address caller);
    error UnauthorizedOwner(address caller);
    error InvalidAddress();
    error InvalidAuthorization();
    error InvalidSender(address sender);
    error InvalidSignerType(uint8 signerType);
    error InvalidNonce(uint192 key, uint64 expected, uint64 supplied);
    error NonceOverflow(uint192 key);
    error InvalidExecutionSelector(bytes4 selector);
    error PolicyViolation_MalformedCalldata();
    error ExecutionFailed(bytes reason);
    error PrefundPaymentFailed();
    error AgentKeyFrozen();
    error UnauthorizedAnomalyGuard(address caller);
    error UnauthorizedGuardianRecovery(address caller);

    uint8 private constant _OWNER_SIGNER = 0;
    uint8 private constant _AGENT_SIGNER = 1;

    /// @notice Selector for execute(bytes32,address,uint256,bytes).
    bytes4 public constant EXECUTE_SELECTOR = bytes4(keccak256("execute(bytes32,address,uint256,bytes)"));
    bytes4 private constant _ERC20_TRANSFER_SELECTOR = bytes4(keccak256("transfer(address,uint256)"));
    bytes4 private constant _ERC20_APPROVE_SELECTOR = bytes4(keccak256("approve(address,uint256)"));
    bytes4 private constant _ERC20_TRANSFER_FROM_SELECTOR = bytes4(keccak256("transferFrom(address,address,uint256)"));
    bytes4 private constant _PAY_CREDITS_SELECTOR = bytes4(keccak256("payCredits(address,uint256)"));

    address public immutable entryPoint;
    address public owner;
    PolicyEngine public immutable policyEngine;
    AnomalyGuard public immutable anomalyGuard;
    GuardianRecoveryModule public immutable guardianRecovery;
    enum AgentStatus {
        ACTIVE,
        FROZEN
    }
    AgentStatus public agentStatus;
    mapping(uint192 nonceKey => uint64 sequence) public nextSequence;

    event OwnerTransferred(address indexed previousOwner, address indexed newOwner);
    event Executed(bytes32 indexed userOpHash, address indexed target, uint256 value, bytes32 callDataHash);

    modifier onlyOwner() {
        if (msg.sender != owner) revert UnauthorizedOwner(msg.sender);
        _;
    }

    modifier onlyEntryPoint() {
        if (msg.sender != entryPoint) revert UnauthorizedEntryPoint(msg.sender);
        _;
    }

    /// @param entryPoint_ The canonical ERC-4337 EntryPoint for this deployment.
    /// @param owner_ The root EOA with unrestricted administrative and execution authority.
    /// @param agentKey_ Initial session key. Pass address(0) to install it later.
    /// @param agentValidUntil_ Initial strict expiry. Ignored when agentKey_ is zero.
    constructor(address entryPoint_, address owner_, address agentKey_, uint48 agentValidUntil_) payable {
        if (entryPoint_ == address(0) || owner_ == address(0)) revert InvalidAddress();
        entryPoint = entryPoint_;
        owner = owner_;
        policyEngine = new PolicyEngine(address(this), owner_);
        anomalyGuard = new AnomalyGuard(address(this), owner_);
        guardianRecovery = new GuardianRecoveryModule(address(this), owner_);
        agentStatus = AgentStatus.ACTIVE;
        if (agentKey_ != address(0)) {
            policyEngine.setAgentKey(agentKey_, agentValidUntil_);
        }
    }

    /// @notice Validates an ERC-4337 v0.6 UserOperation.
    function validateUserOp(
        UserOperation calldata userOp,
        bytes32 userOpHash,
        uint256 missingAccountFunds
    ) external override onlyEntryPoint returns (uint256 validationData) {
        validationData = _validateUserOp(userOp.sender, userOp.nonce, userOp.callData, userOp.signature, userOpHash);
        _payPrefund(missingAccountFunds);
    }

    /// @notice Validates an ERC-4337 v0.7 PackedUserOperation.
    function validateUserOp(
        PackedUserOperation calldata userOp,
        bytes32 userOpHash,
        uint256 missingAccountFunds
    ) external override onlyEntryPoint returns (uint256 validationData) {
        validationData = _validateUserOp(userOp.sender, userOp.nonce, userOp.callData, userOp.signature, userOpHash);
        _payPrefund(missingAccountFunds);
    }

    /// @notice Executes the exact call whose hash was authorized during validation.
    /// @dev The EntryPoint path must consume a PolicyEngine reservation. The root owner
    ///      path intentionally bypasses the agent policy and can execute arbitrary calls.
    function execute(bytes32 userOpHash, address target, uint256 value, bytes calldata data) external payable {
        bool fromEntryPoint = msg.sender == entryPoint;
        if (!fromEntryPoint && msg.sender != owner) revert UnauthorizedOwner(msg.sender);

        bytes4 selector = _selectorOf(data);
        (uint256 tokenAmount, address recipient) = _tokenAmountAndRecipient(data, selector);
        if (fromEntryPoint) {
            if (policyEngine.ownerAuthorizedUserOps(userOpHash)) {
                policyEngine.consumeOwnerUserOp(userOpHash);
            } else {
                policyEngine.consumePendingApproval(
                    userOpHash,
                    target,
                    selector,
                    value,
                    tokenAmount,
                    keccak256(data)
                );
            }
        }

        (bool success, bytes memory result) = target.call{value: value}(data);
        if (!success) _bubbleRevert(result);
        emit Executed(userOpHash, target, value, keccak256(data));
        // Silence the compiler's unused-variable warning while preserving the decoded
        // recipient as an explicit part of the byte-level validation path.
        recipient;
    }

    /// @notice Transfers ownership and updates the policy engine's EIP-712 signer.
    function transferOwnership(address newOwner) external onlyOwner {
        if (newOwner == address(0)) revert InvalidAddress();
        emit OwnerTransferred(owner, newOwner);
        owner = newOwner;
        policyEngine.setOwner(newOwner);
        anomalyGuard.setOwner(newOwner);
        guardianRecovery.synchronizeOwner(newOwner);
    }

    /// @notice Installs or rotates the session key.
    function setAgentKey(address newAgentKey, uint48 validUntil) external onlyOwner {
        policyEngine.setAgentKey(newAgentKey, validUntil);
    }

    /// @notice Revokes the session key without waiting for its expiry.
    function revokeAgentKey() external onlyOwner {
        policyEngine.revokeAgentKey();
    }

    /// @notice Updates per-operation and 24-hour velocity caps.
    function setLimits(uint256 maxPerTxValueWei, uint256 dailyLimitWei) external onlyOwner {
        policyEngine.setLimits(maxPerTxValueWei, dailyLimitWei);
    }

    /// @notice Updates owner-approval escalation behavior.
    function setOwnerApprovalPolicy(bool required, uint256 threshold) external onlyOwner {
        policyEngine.setOwnerApprovalPolicy(required, threshold);
    }

    /// @notice Updates a target allowlist entry.
    function setAllowedTarget(address target, bool allowed) external onlyOwner {
        policyEngine.setAllowedTarget(target, allowed);
    }

    /// @notice Updates a selector allowlist entry.
    function setAllowedSelector(address target, bytes4 selector, bool allowed) external onlyOwner {
        policyEngine.setAllowedSelector(target, selector, allowed);
    }

    /// @notice Updates a direct-transfer recipient allowlist entry.
    function setAllowedRecipient(address recipient, bool allowed) external onlyOwner {
        policyEngine.setAllowedRecipient(recipient, allowed);
    }

    /// @notice Registers the five trusted guardians for social recovery.
    function configureGuardians(address[5] calldata guardians) external onlyOwner {
        guardianRecovery.configureGuardians(guardians);
    }

    /// @notice Configures on-chain anomaly detection sensitivity and schedule.
    function setAnomalyConfiguration(
        uint256 freezeThreshold,
        uint256 alphaBps,
        uint256 baselineTpmScaled,
        uint256 velocityMultiplierBps,
        uint256 zScoreThresholdScaled,
        uint8 expectedStartHourUtc,
        uint8 expectedEndHourUtc
    ) external onlyOwner {
        anomalyGuard.setConfiguration(freezeThreshold, alphaBps, baselineTpmScaled, velocityMultiplierBps, zScoreThresholdScaled, expectedStartHourUtc, expectedEndHourUtc);
    }

    /// @notice Sets the authorized anomaly sentinel watcher.
    function setAnomalySentinel(address sentinel) external onlyOwner {
        anomalyGuard.setSentinel(sentinel);
    }

    /// @notice Adds or removes an interaction from the normal anomaly profile.
    function setKnownInteraction(address target, bytes4 selector, bool known) external onlyOwner {
        anomalyGuard.setKnownInteraction(target, selector, known);
    }

    /// @notice Adds or removes a recipient from the normal anomaly profile.
    function setKnownRecipient(address recipient, bool known) external onlyOwner {
        anomalyGuard.setKnownRecipient(recipient, known);
    }

    /// @notice Owner-controlled recovery from an anomaly freeze.
    function unfreezeAgent() external onlyOwner {
        anomalyGuard.unfreeze();
        agentStatus = AgentStatus.ACTIVE;
    }

    /// @notice Owner or sentinel callback used by AnomalyGuard for persistent freezes.
    function freezeFromAnomalyGuard() external {
        if (msg.sender != address(anomalyGuard)) revert UnauthorizedAnomalyGuard(msg.sender);
        agentStatus = AgentStatus.FROZEN;
    }

    /// @notice Owner-controlled emergency freeze.
    function freezeAgent(bytes32 reason) external onlyOwner {
        anomalyGuard.freeze(reason);
        agentStatus = AgentStatus.FROZEN;
    }

    /// @notice Applies an owner rotation after guardian quorum and timelock execution.
    function recoverOwnerFromGuardians(address newOwner) external {
        if (msg.sender != address(guardianRecovery)) revert UnauthorizedGuardianRecovery(msg.sender);
        if (newOwner == address(0)) revert InvalidAddress();
        emit OwnerTransferred(owner, newOwner);
        owner = newOwner;
        policyEngine.setOwner(newOwner);
        anomalyGuard.setOwner(newOwner);
        guardianRecovery.synchronizeOwner(newOwner);
    }

    /// @notice Applies an agent-key rotation after guardian quorum and timelock execution.
    function recoverAgentFromGuardians(address newAgent) external {
        if (msg.sender != address(guardianRecovery)) revert UnauthorizedGuardianRecovery(msg.sender);
        if (newAgent == address(0)) revert InvalidAddress();
        policyEngine.setAgentKey(newAgent, type(uint48).max);
        anomalyGuard.unfreeze();
        agentStatus = AgentStatus.ACTIVE;
    }

    /// @notice Accepts native currency deposits for UserOperation execution and prefunding.
    receive() external payable {}

    function _validateUserOp(
        address sender,
        uint256 nonce,
        bytes calldata callData,
        bytes calldata authorization,
        bytes32 userOpHash
    ) internal returns (uint256 validationData) {
        if (sender != address(this)) revert InvalidSender(sender);
        if (callData.length < 4) revert PolicyViolation_MalformedCalldata();
        (bytes32 encodedHash, address target, uint256 value, bytes calldata data) = _decodeExecution(callData);
        if (encodedHash != userOpHash) revert PolicyViolation_MalformedCalldata();

        (uint192 nonceKey, uint64 sequence) = _unpackNonce(nonce);
        uint64 expected = nextSequence[nonceKey];
        if (sequence != expected) revert InvalidNonce(nonceKey, expected, sequence);
        if (expected == type(uint64).max) revert NonceOverflow(nonceKey);
        nextSequence[nonceKey] = expected + 1;

        (uint8 signerType, bytes memory signerSignature, bytes memory ownerApprovalSignature, uint48 approvalValidUntil) =
            _decodeAuthorization(authorization);

        if (signerType == _OWNER_SIGNER) {
            if (SignatureLib.recoverEthSigned(userOpHash, signerSignature) != owner) {
                revert InvalidAuthorization();
            }
            policyEngine.authorizeOwnerUserOp(userOpHash);
            // Root-owner operations have unlimited authority and do not create a spend reservation.
            return 0;
        }
        if (signerType != _AGENT_SIGNER) revert InvalidSignerType(signerType);
        if (agentStatus == AgentStatus.FROZEN) revert AgentKeyFrozen();
        if (SignatureLib.recoverEthSigned(userOpHash, signerSignature) != policyEngine.agentKey()) {
            revert InvalidAuthorization();
        }

        bytes4 selector = _selectorOf(data);
        (uint256 tokenAmount, address recipient) = _tokenAmountAndRecipient(data, selector);
        (uint256 riskScore, bool frozen) = anomalyGuard.observeUserOp(target, selector, recipient, value == 0 ? tokenAmount : value);
        if (frozen || riskScore >= anomalyGuard.freezeThreshold()) return 1;
        uint48 validUntil = policyEngine.validateUserOpPolicy(
            userOpHash,
            target,
            value,
            selector,
            recipient,
            tokenAmount,
            keccak256(data),
            ownerApprovalSignature,
            approvalValidUntil
        );
        return uint256(validUntil) << 160;
    }

    function _decodeAuthorization(bytes calldata authorization)
        internal
        pure
        returns (uint8 signerType, bytes memory signerSignature, bytes memory ownerApprovalSignature, uint48 approvalValidUntil)
    {
        if (authorization.length < 128) revert InvalidAuthorization();
        (signerType, signerSignature, ownerApprovalSignature, approvalValidUntil) =
            abi.decode(authorization, (uint8, bytes, bytes, uint48));
    }

    function _decodeExecution(bytes calldata callData)
        internal
        pure
        returns (bytes32 userOpHash, address target, uint256 value, bytes calldata data)
    {
        bytes4 selector;
        assembly {
            selector := calldataload(callData.offset)
        }
        if (selector != EXECUTE_SELECTOR) revert InvalidExecutionSelector(selector);
        if (callData.length < 4 + 128) revert PolicyViolation_MalformedCalldata();

        uint256 dynamicOffset;
        uint256 dataLength;
        assembly {
            userOpHash := calldataload(add(callData.offset, 4))
            target := shr(96, calldataload(add(callData.offset, 36)))
            value := calldataload(add(callData.offset, 68))
            dynamicOffset := calldataload(add(callData.offset, 100))
        }
        if (dynamicOffset < 128 || dynamicOffset % 32 != 0) revert PolicyViolation_MalformedCalldata();
        uint256 dataLengthWord = 4 + dynamicOffset;
        if (dataLengthWord > callData.length - 32) revert PolicyViolation_MalformedCalldata();
        assembly {
            dataLength := calldataload(add(callData.offset, dataLengthWord))
        }
        uint256 dataStart = dataLengthWord + 32;
        if (dataLength > callData.length - dataStart) revert PolicyViolation_MalformedCalldata();
        data = callData[dataStart:dataStart + dataLength];
    }

    function _selectorOf(bytes calldata data) internal pure returns (bytes4 selector) {
        if (data.length == 0) return bytes4(0);
        if (data.length < 4) revert PolicyViolation_MalformedCalldata();
        assembly {
            selector := calldataload(data.offset)
        }
    }

    function _tokenAmountAndRecipient(bytes calldata data, bytes4 selector)
        internal
        pure
        returns (uint256 amount, address recipient)
    {
        if (selector == bytes4(0)) return (0, address(0));
        if (selector == _ERC20_TRANSFER_SELECTOR || selector == _ERC20_APPROVE_SELECTOR) {
            if (data.length < 4 + 64) revert PolicyViolation_MalformedCalldata();
            recipient = _addressWord(data, 0);
            amount = _uintWord(data, 1);
            return (amount, recipient);
        }
        if (selector == _ERC20_TRANSFER_FROM_SELECTOR) {
            if (data.length < 4 + 96) revert PolicyViolation_MalformedCalldata();
            recipient = _addressWord(data, 1);
            amount = _uintWord(data, 2);
        }
        if (selector == _PAY_CREDITS_SELECTOR) {
            if (data.length < 4 + 64) revert PolicyViolation_MalformedCalldata();
            recipient = _addressWord(data, 0);
            amount = _uintWord(data, 1);
        }
    }

    function _addressWord(bytes calldata data, uint256 argumentIndex) internal pure returns (address value) {
        uint256 word = _uintWord(data, argumentIndex);
        if (word >> 160 != 0) revert PolicyViolation_MalformedCalldata();
        value = address(uint160(word));
    }

    function _uintWord(bytes calldata data, uint256 argumentIndex) internal pure returns (uint256 value) {
        uint256 offset = 4 + argumentIndex * 32;
        if (offset > data.length - 32) revert PolicyViolation_MalformedCalldata();
        assembly {
            value := calldataload(add(data.offset, offset))
        }
    }

    function _unpackNonce(uint256 nonce) internal pure returns (uint192 key, uint64 sequence) {
        key = uint192(nonce >> 64);
        sequence = uint64(nonce);
    }

    function _payPrefund(uint256 missingAccountFunds) internal {
        if (missingAccountFunds == 0) return;
        (bool success,) = payable(msg.sender).call{value: missingAccountFunds}("");
        if (!success) revert PrefundPaymentFailed();
    }

    function _bubbleRevert(bytes memory reason) private pure {
        if (reason.length == 0) revert ExecutionFailed(reason);
        assembly {
            revert(add(reason, 32), mload(reason))
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/// @title AnomalyGuard
/// @notice Rolling statistical detector for agent UserOperations with automatic freeze callbacks.
contract AnomalyGuard {
    enum AgentStatus {
        ACTIVE,
        FROZEN
    }

    error UnauthorizedAccount(address caller);
    error UnauthorizedOwner(address caller);
    error UnauthorizedSentinel(address caller);
    error AgentKeyFrozen();
    error InvalidAddress();
    error InvalidThreshold(uint256 threshold);
    error InvalidSchedule(uint8 startHour, uint8 endHour);
    error InvalidOwner();

    uint256 public constant SCORE_SCALE = 1e18;
    uint256 public constant DAY = 1 days;
    uint256 public constant SEVEN_DAYS = 7 days;
    uint256 public constant HOUR = 1 hours;

    address public immutable account;
    address public owner;
    address public sentinel;

    AgentStatus public agentStatus;
    uint256 public freezeThreshold;
    uint256 public alphaBps;
    uint256 public baselineTpmScaled;
    uint256 public velocityMultiplierBps;
    uint256 public zScoreThresholdScaled;
    uint8 public expectedStartHourUtc;
    uint8 public expectedEndHourUtc;

    uint256 public ewmaTpmScaled;
    uint256 public lastObservedAt;
    uint256 public historyWindowStart;
    uint256 public historyCount;
    uint256 public historySumWei;
    uint256 public historySumSquares;
    uint256 public entropyWindowStart;
    uint256 public unfamiliarInteractionCount;
    uint256 public unfamiliarRecipientCount;
    uint256 public frozenAt;
    uint256 public lastRiskScore;
    bytes32 public lastFreezeReason;

    mapping(bytes32 interaction => bool knownInteraction) public knownInteractions;
    mapping(address recipient => bool knownRecipient) public knownRecipients;

    event ConfigurationUpdated(uint256 freezeThreshold, uint256 alphaBps, uint256 baselineTpmScaled, uint256 velocityMultiplierBps, uint256 zScoreThresholdScaled, uint8 expectedStartHourUtc, uint8 expectedEndHourUtc);
    event SentinelUpdated(address indexed previousSentinel, address indexed newSentinel);
    event InteractionProfileUpdated(address indexed target, bytes4 indexed selector, bool known);
    event RecipientProfileUpdated(address indexed recipient, bool known);
    event AnomalyObserved(bytes32 indexed interaction, uint256 velocityRisk, uint256 volatilityRisk, uint256 diversityRisk, uint256 timingRisk, uint256 aggregateRisk, bool frozen);
    event AgentFrozen(bytes32 indexed reason, uint256 riskScore, uint256 timestamp);
    event AgentUnfrozen(uint256 timestamp);

    modifier onlyAccount() {
        if (msg.sender != account) revert UnauthorizedAccount(msg.sender);
        _;
    }

    modifier onlyOwner() {
        if (msg.sender != owner && msg.sender != account) revert UnauthorizedOwner(msg.sender);
        _;
    }

    modifier onlySentinelOrAccount() {
        if (msg.sender != sentinel && msg.sender != account && msg.sender != owner) revert UnauthorizedSentinel(msg.sender);
        _;
    }

    constructor(address account_, address owner_) {
        if (account_ == address(0) || owner_ == address(0)) revert InvalidAddress();
        account = account_;
        owner = owner_;
        agentStatus = AgentStatus.ACTIVE;
        freezeThreshold = 75;
        alphaBps = 2_500;
        baselineTpmScaled = SCORE_SCALE;
        velocityMultiplierBps = 40_000;
        zScoreThresholdScaled = 3 * SCORE_SCALE;
        expectedStartHourUtc = 0;
        expectedEndHourUtc = 24;
        historyWindowStart = block.timestamp;
        entropyWindowStart = block.timestamp;
    }

    /// @notice Updates the detector sensitivity and expected operating schedule.
    function setConfiguration(
        uint256 freezeThreshold_,
        uint256 alphaBps_,
        uint256 baselineTpmScaled_,
        uint256 velocityMultiplierBps_,
        uint256 zScoreThresholdScaled_,
        uint8 expectedStartHourUtc_,
        uint8 expectedEndHourUtc_
    ) external onlyOwner {
        if (freezeThreshold_ == 0 || freezeThreshold_ > 100) revert InvalidThreshold(freezeThreshold_);
        if (alphaBps_ == 0 || alphaBps_ > 10_000 || baselineTpmScaled_ == 0 || velocityMultiplierBps_ == 0 || zScoreThresholdScaled_ == 0) revert InvalidThreshold(freezeThreshold_);
        if (expectedStartHourUtc_ > 24 || expectedEndHourUtc_ > 24) revert InvalidSchedule(expectedStartHourUtc_, expectedEndHourUtc_);
        freezeThreshold = freezeThreshold_;
        alphaBps = alphaBps_;
        baselineTpmScaled = baselineTpmScaled_;
        velocityMultiplierBps = velocityMultiplierBps_;
        zScoreThresholdScaled = zScoreThresholdScaled_;
        expectedStartHourUtc = expectedStartHourUtc_;
        expectedEndHourUtc = expectedEndHourUtc_;
        emit ConfigurationUpdated(freezeThreshold_, alphaBps_, baselineTpmScaled_, velocityMultiplierBps_, zScoreThresholdScaled_, expectedStartHourUtc_, expectedEndHourUtc_);
    }

    /// @notice Authorizes a low-latency sentinel watcher.
    function setSentinel(address newSentinel) external onlyOwner {
        emit SentinelUpdated(sentinel, newSentinel);
        sentinel = newSentinel;
    }

    /// @notice Synchronizes the wallet owner after social recovery or administrative transfer.
    function setOwner(address newOwner) external onlyAccount {
        if (newOwner == address(0)) revert InvalidOwner();
        owner = newOwner;
    }

    /// @notice Marks a target-selector pair as part of the normal interaction profile.
    function setKnownInteraction(address target, bytes4 selector, bool known) external onlyOwner {
        knownInteractions[keccak256(abi.encodePacked(target, selector))] = known;
        emit InteractionProfileUpdated(target, selector, known);
    }

    /// @notice Marks a recipient as part of the normal recipient profile.
    function setKnownRecipient(address recipient, bool known) external onlyOwner {
        knownRecipients[recipient] = known;
        emit RecipientProfileUpdated(recipient, known);
    }

    /// @notice Records a candidate transaction and freezes the account when risk crosses the threshold.
    function observeUserOp(address target, bytes4 selector, address recipient, uint256 amountWei) external onlySentinelOrAccount returns (uint256 riskScore, bool frozen) {
        if (agentStatus == AgentStatus.FROZEN) revert AgentKeyFrozen();
        _refreshWindows();
        uint256 velocityRisk = _velocityRisk();
        uint256 volatilityRisk = _volatilityRisk(amountWei);
        uint256 diversityRisk = _diversityRisk(target, selector, recipient);
        uint256 timingRisk = _timingRisk();
        riskScore = velocityRisk + volatilityRisk + diversityRisk + timingRisk;
        if (riskScore > 100) riskScore = 100;
        lastRiskScore = riskScore;
        bytes32 interaction = keccak256(abi.encodePacked(target, selector));
        if (riskScore >= freezeThreshold) {
            _freeze(keccak256(abi.encode(interaction, riskScore, block.timestamp)));
            frozen = true;
        }
        emit AnomalyObserved(interaction, velocityRisk, volatilityRisk, diversityRisk, timingRisk, riskScore, frozen);
        _updateHistory(amountWei);
        _updateVelocity();
    }

    /// @notice Freezes the agent from the account owner or authorized sentinel.
    function freeze(bytes32 reason) external onlySentinelOrAccount {
        _freeze(reason);
    }

    /// @notice Unfreezes the agent after owner review.
    function unfreeze() external onlyOwner {
        agentStatus = AgentStatus.ACTIVE;
        frozenAt = 0;
        lastFreezeReason = bytes32(0);
        emit AgentUnfrozen(block.timestamp);
    }

    function _freeze(bytes32 reason) internal {
        if (agentStatus == AgentStatus.FROZEN) return;
        agentStatus = AgentStatus.FROZEN;
        frozenAt = block.timestamp;
        lastFreezeReason = reason;
        IAnomalyFreezeCallback(account).freezeFromAnomalyGuard();
        emit AgentFrozen(reason, lastRiskScore, block.timestamp);
    }

    function _refreshWindows() internal {
        if (block.timestamp >= historyWindowStart + SEVEN_DAYS) {
            historyWindowStart = block.timestamp;
            historyCount = 0;
            historySumWei = 0;
            historySumSquares = 0;
        }
        if (block.timestamp >= entropyWindowStart + HOUR) {
            entropyWindowStart = block.timestamp;
            unfamiliarInteractionCount = 0;
            unfamiliarRecipientCount = 0;
        }
    }

    function _velocityRisk() internal view returns (uint256) {
        if (lastObservedAt == 0) return 0;
        uint256 delta = block.timestamp > lastObservedAt ? block.timestamp - lastObservedAt : 1;
        uint256 instantaneousTpm = (60 * SCORE_SCALE) / delta;
        uint256 ewma = ewmaTpmScaled == 0 ? instantaneousTpm : (alphaBps * instantaneousTpm + (10_000 - alphaBps) * ewmaTpmScaled) / 10_000;
        if (ewma * 10_000 <= baselineTpmScaled * velocityMultiplierBps) return 0;
        uint256 excessBps = (ewma * 10_000) / (baselineTpmScaled * velocityMultiplierBps);
        if (excessBps >= 8_000) return 35;
        if (excessBps >= 6_000) return 28;
        return 20;
    }

    function _volatilityRisk(uint256 amountWei) internal view returns (uint256) {
        if (historyCount < 3) return 0;
        uint256 mean = historySumWei / historyCount;
        if (amountWei == mean) return 0;
        if (historySumSquares <= historySumWei * mean) return amountWei > mean ? 30 : 10;
        uint256 variance = (historySumSquares - historySumWei * mean) / historyCount;
        if (variance == 0) return amountWei > mean ? 30 : 10;
        uint256 difference = amountWei > mean ? amountWei - mean : mean - amountWei;
        uint256 zSquared = (difference * difference * SCORE_SCALE) / variance;
        uint256 thresholdSquared = (zScoreThresholdScaled * zScoreThresholdScaled) / SCORE_SCALE;
        if (zSquared >= thresholdSquared * 4) return 30;
        if (zSquared >= thresholdSquared) return 20;
        return 8;
    }

    function _diversityRisk(address target, bytes4 selector, address recipient) internal returns (uint256) {
        uint256 score;
        bytes32 interaction = keccak256(abi.encodePacked(target, selector));
        if (!knownInteractions[interaction]) unfamiliarInteractionCount += 1;
        if (recipient != address(0) && !knownRecipients[recipient]) unfamiliarRecipientCount += 1;
        uint256 unfamiliar = unfamiliarInteractionCount + unfamiliarRecipientCount;
        if (unfamiliar >= 4) score = 30;
        else if (unfamiliar >= 2) score = 22;
        else if (unfamiliar == 1) score = 10;
        return score;
    }

    function _timingRisk() internal view returns (uint256) {
        uint256 hour = (block.timestamp % DAY) / HOUR;
        bool expected;
        if (expectedStartHourUtc == expectedEndHourUtc) expected = true;
        else if (expectedStartHourUtc < expectedEndHourUtc) expected = hour >= expectedStartHourUtc && hour < expectedEndHourUtc;
        else expected = hour >= expectedStartHourUtc || hour < expectedEndHourUtc;
        return expected ? 0 : 15;
    }

    function _updateHistory(uint256 amountWei) internal {
        historyCount += 1;
        historySumWei += amountWei;
        if (amountWei <= type(uint128).max) historySumSquares += amountWei * amountWei;
        else historySumSquares = type(uint256).max;
    }

    function _updateVelocity() internal {
        uint256 delta = lastObservedAt == 0 || block.timestamp <= lastObservedAt ? 1 : block.timestamp - lastObservedAt;
        uint256 instantaneousTpm = (60 * SCORE_SCALE) / delta;
        ewmaTpmScaled = ewmaTpmScaled == 0 ? instantaneousTpm : (alphaBps * instantaneousTpm + (10_000 - alphaBps) * ewmaTpmScaled) / 10_000;
        lastObservedAt = block.timestamp;
    }
}

interface IAnomalyFreezeCallback {
    function freezeFromAnomalyGuard() external;
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/// @title GuardianRecoveryModule
/// @notice 3-of-5 guardian social recovery with a 48-hour execution delay and owner veto.
/// @dev The smart account remains the sole authority that can configure this module or
///      accept its final recovery callback. Guardian approvals are counted by address,
///      so duplicate signatures cannot satisfy quorum.
contract GuardianRecoveryModule {
    uint256 public constant GUARDIAN_COUNT = 5;
    uint256 public constant QUORUM = 3;
    uint256 public constant RECOVERY_DELAY = 48 hours;

    enum RecoveryTarget {
        OWNER,
        AGENT
    }

    enum ProposalStatus {
        NONE,
        ACTIVE,
        PENDING,
        EXECUTED,
        VETOED
    }

    struct RecoveryProposal {
        uint256 id;
        address proposer;
        address newKey;
        RecoveryTarget target;
        ProposalStatus status;
        uint8 approvalCount;
        uint48 createdAt;
        uint48 executableAfter;
        uint48 executedAt;
        uint48 vetoedAt;
    }

    error UnauthorizedWallet(address caller);
    error UnauthorizedGuardian(address caller);
    error UnauthorizedOwner(address caller);
    error InvalidAddress();
    error DuplicateGuardian(address guardian);
    error GuardianSetAlreadyConfigured();
    error InvalidRecoveryId(uint256 recoveryId);
    error InvalidNewKey();
    error InvalidProposalStatus(ProposalStatus status);
    error GuardianAlreadyApproved(uint256 recoveryId, address guardian);
    error QuorumNotReached(uint256 recoveryId, uint256 approvals);
    error RecoveryTimelockActive(uint256 recoveryId, uint48 executableAfter, uint256 timestamp);
    error RecoveryExecutionFailed();

    address public immutable wallet;
    address public owner;
    bool public guardiansConfigured;
    uint256 public nextRecoveryId = 1;

    address[GUARDIAN_COUNT] private _guardians;
    mapping(address guardian => bool) public isGuardian;
    mapping(uint256 recoveryId => RecoveryProposal) public proposals;
    mapping(uint256 recoveryId => mapping(address guardian => bool)) public hasApproved;

    event GuardiansConfigured(address[GUARDIAN_COUNT] guardians);
    event OwnerSynchronized(address indexed previousOwner, address indexed newOwner);
    event RecoveryInitiated(uint256 indexed recoveryId, address indexed proposer, address indexed newKey, RecoveryTarget target);
    event GuardianApprovalAdded(uint256 indexed recoveryId, address indexed guardian, uint8 approvalCount);
    event RecoveryQueued(uint256 indexed recoveryId, uint48 executableAfter);
    event RecoveryVetoed(uint256 indexed recoveryId, address indexed owner, uint48 timestamp);
    event RecoveryExecuted(uint256 indexed recoveryId, address indexed newKey, RecoveryTarget target, uint48 timestamp);

    modifier onlyWallet() {
        if (msg.sender != wallet) revert UnauthorizedWallet(msg.sender);
        _;
    }

    modifier onlyGuardian() {
        if (!isGuardian[msg.sender]) revert UnauthorizedGuardian(msg.sender);
        _;
    }

    constructor(address wallet_, address owner_) {
        if (wallet_ == address(0) || owner_ == address(0)) revert InvalidAddress();
        wallet = wallet_;
        owner = owner_;
    }

    /// @notice Registers the complete trusted guardian set exactly once.
    function configureGuardians(address[GUARDIAN_COUNT] calldata guardians) external onlyWallet {
        if (guardiansConfigured) revert GuardianSetAlreadyConfigured();
        for (uint256 index = 0; index < GUARDIAN_COUNT; index++) {
            address guardian = guardians[index];
            if (guardian == address(0)) revert InvalidAddress();
            for (uint256 previous = 0; previous < index; previous++) {
                if (guardians[previous] == guardian) revert DuplicateGuardian(guardian);
            }
            _guardians[index] = guardian;
            isGuardian[guardian] = true;
        }
        guardiansConfigured = true;
        emit GuardiansConfigured(guardians);
    }

    /// @notice Synchronizes the veto authority after the wallet owner changes.
    function synchronizeOwner(address newOwner) external onlyWallet {
        if (newOwner == address(0)) revert InvalidAddress();
        emit OwnerSynchronized(owner, newOwner);
        owner = newOwner;
    }

    /// @notice Returns the five configured guardians in deterministic order.
    function getGuardians() external view returns (address[GUARDIAN_COUNT] memory) {
        return _guardians;
    }

    /// @notice Creates a recovery proposal. Any one registered guardian may initiate it.
    function initiateRecovery(address newKey, RecoveryTarget target) external onlyGuardian returns (uint256 recoveryId) {
        if (!guardiansConfigured) revert InvalidProposalStatus(ProposalStatus.NONE);
        if (newKey == address(0)) revert InvalidNewKey();
        recoveryId = nextRecoveryId++;
        proposals[recoveryId] = RecoveryProposal({
            id: recoveryId,
            proposer: msg.sender,
            newKey: newKey,
            target: target,
            status: ProposalStatus.ACTIVE,
            approvalCount: 0,
            createdAt: uint48(block.timestamp),
            executableAfter: 0,
            executedAt: 0,
            vetoedAt: 0
        });
        emit RecoveryInitiated(recoveryId, msg.sender, newKey, target);
    }

    /// @notice Adds one distinct guardian approval and starts the 48-hour delay at quorum.
    function approveRecovery(uint256 recoveryId) external onlyGuardian {
        RecoveryProposal storage proposal = _proposal(recoveryId);
        if (proposal.status != ProposalStatus.ACTIVE) revert InvalidProposalStatus(proposal.status);
        if (hasApproved[recoveryId][msg.sender]) revert GuardianAlreadyApproved(recoveryId, msg.sender);
        hasApproved[recoveryId][msg.sender] = true;
        proposal.approvalCount += 1;
        emit GuardianApprovalAdded(recoveryId, msg.sender, proposal.approvalCount);
        if (proposal.approvalCount >= QUORUM) {
            proposal.status = ProposalStatus.PENDING;
            proposal.executableAfter = uint48(block.timestamp + RECOVERY_DELAY);
            emit RecoveryQueued(recoveryId, proposal.executableAfter);
        }
    }

    /// @notice Lets the legitimate owner cancel an active or queued recovery immediately.
    /// @dev All guardian approval bits are cleared so the vetoed proposal cannot be resumed.
    function vetoRecovery(uint256 recoveryId) external {
        if (msg.sender != owner) revert UnauthorizedOwner(msg.sender);
        RecoveryProposal storage proposal = _proposal(recoveryId);
        if (proposal.status != ProposalStatus.ACTIVE && proposal.status != ProposalStatus.PENDING) {
            revert InvalidProposalStatus(proposal.status);
        }
        proposal.status = ProposalStatus.VETOED;
        proposal.vetoedAt = uint48(block.timestamp);
        for (uint256 index = 0; index < GUARDIAN_COUNT; index++) {
            delete hasApproved[recoveryId][_guardians[index]];
        }
        proposal.approvalCount = 0;
        emit RecoveryVetoed(recoveryId, msg.sender, uint48(block.timestamp));
    }

    /// @notice Executes a queued recovery after the entire 48-hour delay has elapsed.
    function executeRecovery(uint256 recoveryId) external onlyGuardian {
        RecoveryProposal storage proposal = _proposal(recoveryId);
        if (proposal.status != ProposalStatus.PENDING) revert InvalidProposalStatus(proposal.status);
        if (block.timestamp < proposal.executableAfter) {
            revert RecoveryTimelockActive(recoveryId, proposal.executableAfter, block.timestamp);
        }
        proposal.status = ProposalStatus.EXECUTED;
        proposal.executedAt = uint48(block.timestamp);
        if (proposal.target == RecoveryTarget.OWNER) {
            IGuardianRecoveryWallet(wallet).recoverOwnerFromGuardians(proposal.newKey);
        } else {
            IGuardianRecoveryWallet(wallet).recoverAgentFromGuardians(proposal.newKey);
        }
        emit RecoveryExecuted(recoveryId, proposal.newKey, proposal.target, uint48(block.timestamp));
    }

    function _proposal(uint256 recoveryId) internal view returns (RecoveryProposal storage proposal) {
        proposal = proposals[recoveryId];
        if (proposal.id == 0) revert InvalidRecoveryId(recoveryId);
    }
}

interface IGuardianRecoveryWallet {
    function recoverOwnerFromGuardians(address newOwner) external;
    function recoverAgentFromGuardians(address newAgent) external;
}

